sp_widget.css:
/* =========================================================
   GATENOW LANDING · CALL TO ACTION
   Service Portal widget · CSS / SCSS

   Selectors are written out in full. The Service Portal Sass
   compiler does not support parent selector concatenation.

   Design notes worth keeping:

   1. Two columns, left aligned. An earlier version centred
      everything on an open band with a wide arc and a radial
      glow behind it. The arc crossed the content, the glow read
      as a grey oval rather than light, and the centred stack
      had nothing holding it to the page. Both are gone.

   2. The only structure here is a hairline rule at the top of
      the section and one between the two columns. That is
      enough. The page has already used cards and boxes, so the
      close is deliberately plain.

   3. The single solid blue button is the same blue as the
      hero's primary action, which is what makes the page close
      where it opened.

   4. Nothing is held at opacity zero in a base rule. The
      from-state comes from animation-fill-mode backwards, so if
      animation is blocked the content still renders.
   ========================================================= */

/* ---------- typeface ----------
   Shared with the other landing widgets. If they sit on one
   page, keep a single copy in a Style Sheet record attached to
   the theme and delete this block from the widgets.
   ------------------------------------------------------------- */

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_regular.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_medium.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_semibold.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_bold.woff2") format("woff2");
}


/* ---------- palette ---------- */
$gnc-navy:      #0a2540;
$gnc-blue:      #1560e0;
$gnc-blue-dk:   #0f4cbb;
$gnc-blue-soft: #eef3fd;
$gnc-body:      #55677f;
$gnc-hair:      #e2e9f4;
$gnc-white:     #ffffff;

$gnc-ease:      cubic-bezier(0.45, 0.05, 0.25, 1);

$gnc-font: "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;


/* =========================================================
   BAND
   ========================================================= */

.gnc-cta {
  position: relative;
  width: 100%;
  padding: 104px 24px 112px;
  font-family: $gnc-font;
  color: $gnc-navy;
  background: $gnc-white;
}

.gnc-cta *,
.gnc-cta *::before,
.gnc-cta *::after { box-sizing: border-box; }

.gnc-cta__inner {
  position: relative;
  max-width: 1120px;
  margin: 0 auto;
}

/* the only line marking the start of the section */
.gnc-cta__inner::before {
  content: "";
  position: absolute;
  top: -104px;
  right: 0;
  left: 0;
  height: 1px;
  background: $gnc-hair;
}

.gnc-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.12fr) minmax(0, 0.88fr);
  gap: 72px;
  align-items: center;
}


/* =========================================================
   LEAD
   ========================================================= */

.gnc-lead { min-width: 0; }

.gnc-cta .gnc-eyebrow {
  display: inline-flex;
  align-items: center;
  padding: 8px 18px;
  margin: 0 0 24px;
  border-radius: 999px;
  background: $gnc-blue-soft;
  color: $gnc-blue;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.gnc-cta .gnc-heading {
  margin: 0;
  max-width: 520px;
  font-size: 46px;
  font-weight: 700;
  line-height: 1.14;
  letter-spacing: -0.032em;
  color: $gnc-navy;
}

@supports (font-size: clamp(30px, 3.6vw, 46px)) {
  .gnc-cta .gnc-heading { font-size: clamp(30px, 3.6vw, 46px); }
}

.gnc-cta .gnc-sub {
  max-width: 520px;
  margin: 20px 0 0;
  padding: 0;
  font-size: 17.5px;
  font-weight: 400;
  line-height: 1.68;
  color: $gnc-body;
}


/* =========================================================
   ACTION
   ========================================================= */

.gnc-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px 28px;
  margin-top: 34px;
}

.gnc-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 14px;
  height: 62px;
  padding: 0 20px 0 32px;
  border-radius: 999px;
  overflow: hidden;
  background: $gnc-blue;
  color: $gnc-white;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.01em;
  text-decoration: none;
  box-shadow: 0 14px 30px rgba(21, 96, 224, 0.26);
  transition: transform 0.55s $gnc-ease,
              background 0.55s $gnc-ease,
              box-shadow 0.55s $gnc-ease;
}

.gnc-btn:hover,
.gnc-btn:focus {
  transform: translateY(-3px);
  background: $gnc-blue-dk;
  color: $gnc-white;
  box-shadow: 0 22px 44px rgba(21, 96, 224, 0.34);
  text-decoration: none;
}

.gnc-btn__label { position: relative; z-index: 2; }

.gnc-btn__arrow {
  position: relative;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.18);
  color: $gnc-white;
  font-size: 13px;
  transition: transform 0.55s $gnc-ease, background 0.55s $gnc-ease;
}

.gnc-btn:hover .gnc-btn__arrow,
.gnc-btn:focus .gnc-btn__arrow {
  transform: translateX(4px);
  background: rgba(255, 255, 255, 0.28);
}

/* a single pass of light across the face on hover */
.gnc-btn__shine {
  position: absolute;
  top: 0;
  bottom: 0;
  left: -60%;
  z-index: 1;
  width: 45%;
  transform: skewX(-18deg);
  background: linear-gradient(90deg,
              rgba(255, 255, 255, 0) 0%,
              rgba(255, 255, 255, 0.22) 50%,
              rgba(255, 255, 255, 0) 100%);
  transition: left 0.75s $gnc-ease;
  pointer-events: none;
}

.gnc-btn:hover .gnc-btn__shine,
.gnc-btn:focus .gnc-btn__shine { left: 115%; }

.gnc-link {
  position: relative;
  display: inline-flex;
  align-items: center;
  padding: 4px 0 6px;
  color: $gnc-body;
  font-size: 16px;
  font-weight: 500;
  text-decoration: none;
  transition: color 0.55s $gnc-ease;
}

.gnc-link:hover,
.gnc-link:focus {
  color: $gnc-blue-dk;
  text-decoration: none;
}

.gnc-link__rule {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 1px;
  background: currentColor;
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.55s $gnc-ease;
}

.gnc-link:hover .gnc-link__rule,
.gnc-link:focus .gnc-link__rule { transform: scaleX(1); }

.gnc-cta .gnc-note {
  margin: 26px 0 0;
  padding: 0;
  font-size: 14.5px;
  color: rgba(85, 103, 127, 0.82);
}


/* =========================================================
   ASIDE
   What is on the page the button opens.
   ========================================================= */

.gnc-aside {
  position: relative;
  min-width: 0;
  padding-left: 72px;
}

/* the rule between the columns, not a box around them */
.gnc-aside::before {
  content: "";
  position: absolute;
  top: 4px;
  bottom: 4px;
  left: 0;
  width: 1px;
  background: $gnc-hair;
}

.gnc-cta .gnc-aside__label {
  margin: 0 0 22px;
  padding: 0;
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(85, 103, 127, 0.72);
}

.gnc-cta .gnc-facts {
  margin: 0;
  padding: 0;
  list-style: none;
}

.gnc-fact {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 16px;
  padding: 18px 0;
  border-bottom: 1px solid $gnc-hair;
}

.gnc-fact--1 { padding-top: 0; }

.gnc-fact:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}

.gnc-fact__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 13px;
  background: $gnc-blue-soft;
  color: $gnc-blue;
  font-size: 15px;
  flex-shrink: 0;
  transition: background 0.55s $gnc-ease, color 0.55s $gnc-ease;
}

.gnc-fact:hover .gnc-fact__icon {
  background: $gnc-blue;
  color: $gnc-white;
}

.gnc-fact__copy {
  display: block;
  min-width: 0;
  padding-top: 1px;
}

.gnc-fact__label {
  display: block;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.015em;
  color: $gnc-navy;
}

.gnc-fact__detail {
  display: block;
  margin-top: 5px;
  font-size: 14.5px;
  line-height: 1.6;
  color: $gnc-body;
}

.gnc-cta a:focus-visible {
  outline: 2px solid $gnc-blue;
  outline-offset: 4px;
}


/* =========================================================
   MOTION
   ========================================================= */

@media (prefers-reduced-motion: no-preference) {

  @keyframes gncRise {
    from { opacity: 0; transform: translateY(18px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  .gnc-cta .gnc-eyebrow,
  .gnc-cta .gnc-heading,
  .gnc-cta .gnc-sub,
  .gnc-actions,
  .gnc-cta .gnc-note,
  .gnc-cta .gnc-aside__label {
    animation: gncRise 0.7s $gnc-ease backwards;
  }

  .gnc-cta .gnc-eyebrow     { animation-delay: 0.06s; }
  .gnc-cta .gnc-heading     { animation-delay: 0.13s; }
  .gnc-cta .gnc-sub         { animation-delay: 0.20s; }
  .gnc-actions              { animation-delay: 0.27s; }
  .gnc-cta .gnc-note        { animation-delay: 0.34s; }
  .gnc-cta .gnc-aside__label { animation-delay: 0.24s; }

  .gnc-fact {
    animation: gncRise 0.66s $gnc-ease backwards;
  }

  .gnc-fact--1 { animation-delay: 0.32s; }
  .gnc-fact--2 { animation-delay: 0.40s; }
  .gnc-fact--3 { animation-delay: 0.48s; }
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1024px) {

  .gnc-cta { padding: 84px 20px 92px; }

  .gnc-cta__inner::before { top: -84px; }

  .gnc-grid {
    grid-template-columns: minmax(0, 1fr);
    gap: 46px;
  }

  .gnc-aside {
    padding-left: 0;
    padding-top: 40px;
  }

  /* the rule turns and sits above the column instead of beside it */
  .gnc-aside::before {
    top: 0;
    right: 0;
    bottom: auto;
    left: 0;
    width: auto;
    height: 1px;
  }

  .gnc-cta .gnc-heading,
  .gnc-cta .gnc-sub { max-width: 620px; }
}

@media (max-width: 620px) {

  .gnc-cta { padding: 64px 16px 72px; }

  .gnc-cta__inner::before { top: -64px; }

  .gnc-actions {
    flex-direction: column;
    align-items: stretch;
    gap: 16px;
  }

  .gnc-btn {
    width: 100%;
    height: 58px;
    justify-content: center;
    font-size: 16px;
  }

  .gnc-link { justify-content: center; }

  .gnc-fact {
    grid-template-columns: 36px minmax(0, 1fr);
    gap: 13px;
  }

  .gnc-fact__icon {
    width: 36px;
    height: 36px;
    border-radius: 11px;
    font-size: 13px;
  }

  .gnc-cta .gnc-sub { font-size: 16px; }
  .gnc-fact__detail { font-size: 14px; }
}

@media (prefers-reduced-motion: reduce) {
  .gnc-cta * { transition: none; }
  .gnc-btn:hover { transform: none; }
}

sp_widget.script:
(function () {

  /* =========================================================
     GATENOW LANDING · CALL TO ACTION
     Service Portal widget · Server script

     Copy lives here rather than in the template so every string
     passes through gs.getMessage and stays translatable. No
     table access, so no ACL considerations apply.

     Note on option names: every widget instance already has a
     built in "title" field, so options.title returns the
     instance title rather than anything you set. The heading
     option is named heading for that reason. The same applies
     to color, glyph and size.
     ========================================================= */

  function opt(name, fallback) {
    var value = options[name];
    if (value === null || value === undefined || value === '') {
      return fallback;
    }
    return value.toString();
  }

  data.regionLabel = opt('region_label', gs.getMessage('Explore open programs'));

  data.eyebrow = opt('eyebrow', gs.getMessage('Open programs'));
  data.heading = opt('heading', gs.getMessage('Start with the list, not the blank page'));

  data.subhead = opt('subhead', gs.getMessage(
    'Open programs sit in one place, each with its criteria, its funding range ' +
    'and its closing date. Twenty minutes with that list will tell you more ' +
    'than a week of guessing, and it is the difference between a bid that fits ' +
    'and one that never stood a chance.'));

  data.primaryLabel = opt('primary_label', gs.getMessage('Explore programs'));
  data.primaryUrl   = opt('primary_url', '?id=opportunities');

  /* One action only. The hero already carries the link to the process
     section, and repeating it here would split the attention of a
     reader who has just finished reading that section. Set these two
     options if a second action is ever needed. */
  data.secondaryLabel = opt('secondary_label', '');
  data.secondaryUrl   = opt('secondary_url', '');

  /* The right hand column. These are the three things every
     program record actually carries, so the reader knows what
     they are opening rather than being sold it again. */
  data.factsLabel = opt('facts_label', gs.getMessage('What each program tells you'));

  data.facts = [
    {
      icon  : 'fa-bullseye',
      label : gs.getMessage('What it funds'),
      detail: gs.getMessage('The categories in scope, the costs you can claim against, and the size of award on offer.')
    },
    {
      icon  : 'fa-users',
      label : gs.getMessage('Who can apply'),
      detail: gs.getMessage('Organisation types, the area it covers, and any restriction that would rule you out.')
    },
    {
      icon  : 'fa-calendar-o',
      label : gs.getMessage('When it closes'),
      detail: gs.getMessage('Opening and closing dates, so a deadline never arrives without warning.')
    }
  ];

  data.note = opt('note', gs.getMessage(
    'Nothing to fill in yet. Have a look first, apply when something fits.'));

})();
